python3 << 'EOF'
import json
import subprocess

result = subprocess.run(
    ['curl', '-s', '-H', f'Authorization: token {subprocess.run(["gh", "auth", "token"], capture_output=True, text=True).stdout.strip()}',
     'https://api.github.com/repos/wp-media/backwpup-pro/issues?state=open&per_page=100'],
    capture_output=True,
    text=True
)

issues_data = json.loads(result.stdout)
unassigned_issues = [i for i in issues_data if i['assignee'] is None]

def estimate_story_points(issue):
    title = issue['title'].lower()
    body = (issue['body'] or '')[:300].lower()
    labels = [l['name'].lower() for l in issue['labels']]

    points = 3

    if any(kw in title for kw in ['typo', 'wording', 'rename', 'fix link', 'bump']):
        points = 1
    elif any(kw in title for kw in ['update', 'add test', 'docs', 'comment']):
        points = 2
    elif any(kw in title for kw in ['overhaul', 'migrate', 'restructure', 'major']):
        points = 8
    elif any(kw in title for kw in ['refactor', 'rewrite', 'architecture']):
        points = 5
    elif 'chore' in title or 'deps' in title:
        points = 2

    if 'fix:' in title or 'fix(' in title:
        points = max(1, points - 1)

    if 'priority:critical' in labels:
        points = min(8, points + 1)

    return points

issue_list = []
for issue in unassigned_issues:
    points = estimate_story_points(issue)

    if 'fix:' in issue['title'].lower():
        issue_type = 'bug'
    elif any(x in issue['title'].lower() for x in ['refactor', 'test', 'docs', 'chore', 'deps']):
        issue_type = 'debt'
    else:
        issue_type = 'feature'

    labels_lower = [x['name'].lower() for x in issue['labels']]
    if 'priority:critical' in labels_lower:
        priority = 'critical'
    elif 'priority:high' in labels_lower:
        priority = 'high'
    else:
        priority = 'normal'

    issue_list.append({
        'number': issue['number'],
        'title': issue['title'],
        'type': issue_type,
        'points': points,
        'priority': priority,
    })

priority_val = {'critical': 0, 'high': 1, 'normal': 2}
type_val = {'bug': 0, 'feature': 1, 'debt': 2}

issue_list.sort(key=lambda x: (
    priority_val[x['priority']],
    type_val[x['type']],
    -x['points']
))

capacity = 16
shortlist = []
total_points = 0

for issue in issue_list:
    if total_points + issue['points'] <= capacity:
        shortlist.append(issue)
        total_points += issue['points']
        print(f"✓ #{issue['number']:4d} {issue['points']} SP | Running total: {total_points} ({issue['type']}, {issue['priority']})")
    else:
        if len(shortlist) < 10:  # Only print first few that don't fit
            print(f"✗ #{issue['number']:4d} {issue['points']} SP | Would exceed ({total_points + issue['points']})")

    if total_points >= capacity:
        break

print(f"\nTotal: {len(shortlist)} issues, {total_points} SP")

EOF

